'use strict';
// Career is deliberately independent of the class apps and their storage keys.
const CAREER_KEY='recall-career-v1';
let C, saved={read:{},passed:{},review:{},spoken:{},milestones:{},track:'all'}, view='home', moduleId=0, activeLesson=null, quiz=null, mock=null, flash=null, lab=null;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function jumble(items){let a=shuffle(items);if(a.length>1&&a.every((x,i)=>x===items[i]))a.push(a.shift());return a}
function persist(){try{localStorage.setItem(CAREER_KEY,JSON.stringify(saved))}catch(e){$('#career-status').innerHTML='<div class="c-alert">Your browser could not save progress. You can keep practicing, but progress may be lost when you leave.</div>'}stats()}
function restore(){try{const raw=JSON.parse(localStorage.getItem(CAREER_KEY)||'null');if(raw&&typeof raw==='object'){for(const k of ['read','passed','review','spoken','milestones'])if(raw[k]&&typeof raw[k]==='object'&&!Array.isArray(raw[k]))saved[k]=raw[k];if(C.tracks.some(t=>t.id===raw.track))saved.track=raw.track}}catch(e){$('#career-status').innerHTML='<div class="c-alert">Saved career progress could not be read. A fresh session is available; class progress is unaffected.</div>'}}
function track(){return C.tracks.find(t=>t.id===saved.track)||C.tracks[0]}
function lessons(){return C.lessons.filter(l=>track().modules.includes(l.module))}
function questions(){const ids=new Set(lessons().map(l=>l.id));return C.questions.filter(q=>ids.has(q.lesson))}
function lessonFor(id){return C.lessons.find(l=>l.id===id)}
function modFor(l){return C.modules.find(m=>m.id===l.module)}
function btn(action,text,value='',cls=''){return `<button class="${cls}" data-action="${action}" data-value="${esc(value)}">${esc(text)}</button>`}
function sourceLinks(ids){return `<div class="c-source">Concept references: ${ids.map(id=>{const s=C.sources.find(s=>s.id===id);return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`}).join('')}</div>`}
function bar(n,total,label){return `<div class="c-progress"><small>${esc(label)} · ${n} / ${total}</small><progress value="${n}" max="${Math.max(total,1)}" aria-label="${esc(label)}"></progress></div>`}
function stats(){if(C)$('#career-stats').textContent=`${lessons().filter(l=>saved.read[l.id]).length}/${lessons().length} lessons read · ${questions().filter(q=>saved.passed[q.id]).length}/${questions().length} checks cleared`}
function setPage(html){$('#career-app').innerHTML=html;stats()}
function focusPage(){window.scrollTo({top:0,behavior:'instant'});$('#career-app').focus({preventScroll:true})}
const views=[['home','Your roadmap'],['learn','Learn & practice'],['interview','Interview room'],['labs','Work through cases'],['terms','Flashcards & terms'],['research','Roles & research']];
function nav(){ $('#career-nav').innerHTML=views.map(([id,title])=>`<button data-action="view" data-value="${id}" ${view===id?'class="active" aria-current="page"':''}>${title}</button>`).join('') }
function navigate(to){view=to;quiz=null;mock=null;flash=null;lab=null;activeLesson=null;nav();({home:home,learn:learn,interview:interviewHome,labs:labsHome,terms:terms,research:research}[to]||home)();focusPage()}
function home(){const ls=lessons(),qs=questions(),next=ls.find(l=>!saved.read[l.id])||ls[0],weak=qs.filter(q=>saved.review[q.id]);setPage(`<div class="c-hero"><div class="eyebrow">ENTRY LEVEL · MAY 2027</div><h1>Your first technology job starts with understanding.</h1><p>Build the basics, practice decisions, then explain them out loud. Use real examples from your classes, projects and work experience.</p><div class="c-row">${btn('lesson',saved.read[next.id]?'Revisit your first lesson':'Continue learning',next.id,'primary')}${btn('view','Explore the roles','research')}</div></div><div class="c-row"><span class="c-tag">${esc(track().title)}</span><span class="c-tag">No typing required</span><span class="c-tag">Separate from classes</span></div><p>${esc(track().about)}</p><div class="c-grid"><div class="c-card"><h2>Understand it</h2>${bar(ls.filter(l=>saved.read[l.id]).length,ls.length,'Lessons read')}${btn('view','Open learning path','learn')}<p>Read completion and practice completion are tracked separately.</p></div><div class="c-card"><h2>Remember & explain it</h2>${bar(qs.filter(q=>saved.passed[q.id]).length,qs.length,'Practice checks cleared')}${btn('review',`Review ${weak.length} missed checks`)}${btn('view','Practice speaking','interview')}<p>These are practice milestones, not a claim that you are job-ready.</p></div></div><h2>From now to May 2027</h2><p>A suggested plan, not employer deadlines. Start applying while you keep learning; check each posting’s eligibility and start date.</p><div class="c-milestones"><div class="c-card"><span class="c-tag">FALL 2026</span><h3>Choose & apply</h3><p>Compare 2–3 role families. Prepare a one-page résumé, collect real project examples and check new-graduate openings regularly.</p></div><div class="c-card"><span class="c-tag">WINTER 2026–27</span><h3>Show your work</h3><p>Finish the shared foundation, deepen your chosen path and build one small work sample. Rehearse answers with someone who can give feedback.</p></div><div class="c-card"><span class="c-tag">SPRING 2027</span><h3>Tailor & rehearse</h3><p>Keep applying. Match preparation to each posting, confirm May graduation/start timing and practice the announced interview format.</p></div></div><h2>My preparation checklist</h2><div class="c-rubric">${['I chose two or three role families to prioritize.','I can explain one real class or personal project and my contribution.','I prepared true examples of teamwork, a mistake and a difficult problem.','I checked start dates and eligibility on roles I am applying to.','I practiced speaking with a person and asked for specific feedback.'].map((t,i)=>`<label><input type="checkbox" data-milestone="${i}" ${saved.milestones[i]?'checked':''}>${esc(t)}</label>`).join('')}</div>`)}
function learn(){const ls=lessons();setPage(`<div class="eyebrow">${esc(track().title)} · LEARN, TRY, EXPLAIN</div><h1>One idea at a time.</h1><p>Each lesson explains the words first, shows a workplace example, then gives you relevant practice. Use the path selector to focus on a role.</p>${btn('practice','Mixed practice: 10 checks','mixed','primary')} ${btn('review','Review missed checks')}<div class="c-grid">${C.modules.filter(m=>track().modules.includes(m.id)).map(m=>{const group=ls.filter(l=>l.module===m.id),pool=C.questions.filter(q=>group.some(l=>l.id===q.lesson));return `<section class="c-card"><div class="c-number">${m.id}</div><h2>${esc(m.title)}</h2>${m.id===9?'<span class="c-tag">Posting-dependent · introduction only</span>':''}<p>${esc(m.why)}</p>${bar(group.filter(l=>saved.read[l.id]).length,group.length,'Read')}${bar(pool.filter(q=>saved.passed[q.id]).length,pool.length,'Checks cleared')}<div class="c-list">${group.map(l=>btn('lesson',`${saved.read[l.id]?'✓ ':''}${l.title}`,l.id)).join('')}</div>${btn('module-practice','Practice this topic',m.id)}</section>`}).join('')}</div>`)}
function termDetails(l){return `<details><summary>Words used in this lesson</summary><dl class="c-terms">${l.terms.map(t=>`<dt>${esc(t.term)}</dt><dd>${esc(t.definition)}</dd>`).join('')}</dl></details>`}
function openLesson(id){activeLesson=id;const l=lessonFor(id),ls=lessons(),pos=ls.findIndex(x=>x.id===id);setPage(`<article class="c-lesson"><div class="eyebrow">TOPIC ${l.module} · ${esc(modFor(l).title)}</div><h1>${esc(l.title)}</h1><span class="c-tag">Lesson ${pos+1} of ${ls.length} on your path</span>${l.module===9?'<p class="c-note">For coding-focused postings. These lessons introduce the thinking; you also need to implement and test code in a programming environment.</p>':''}${termDetails(l)}${l.teach.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="c-note"><h3>Picture the actual work</h3><p>${esc(l.example)}</p></div>${sourceLinks(l.sources)}<div class="c-actions">${btn('lesson-practice','Try this lesson',l.id,'primary')}${btn('continue','Mark read & next lesson',l.id)}${btn('view','Back to learning','learn')}</div><p class="c-callout">Marking a lesson read fills the reading bar. Clear its questions to fill the practice bar.</p></article>`);focusPage()}
function continueLesson(id){saved.read[id]=true;persist();const seq=lessons(),i=seq.findIndex(l=>l.id===id);if(i<seq.length-1)return openLesson(seq[i+1].id);const remaining=seq.filter(l=>!saved.read[l.id]);setPage(`<div class="c-hero"><div class="eyebrow">${esc(track().title)}</div><h1>${remaining.length?'You reached the last lesson.':'All lessons on this path read ✓'}</h1><p>${remaining.length?`${remaining.length} earlier lessons still need a visit.`:'Now strengthen recall and practice explaining your reasoning.'}</p></div><div class="c-actions">${remaining.length?btn('lesson','Continue unread lessons',remaining[0].id,'primary'):btn('practice','Practice this path','mixed','primary')}${btn('view','Go to interview room','interview')}${btn('view','Back to learning','learn')}</div>`);focusPage()}
function prepare(q){return {...q,choices:q.kind==='mc'?shuffle(q.options):jumble(q.bank),picked:[]}}
function startQuiz(pool,lesson=null){if(!pool.length){setPage(`<h1>Nothing waiting for review.</h1><p>Missed checks will appear here. You can start a fresh mixed round whenever you want.</p>${btn('practice','Start mixed practice','mixed','primary')}`);return}quiz={queue:pool.map(prepare),index:0,total:pool.length,cleared:new Set(),attempts:0,first:0,lesson,graded:false};renderQuestion();focusPage()}
function current(){return quiz.queue[quiz.index]}
function renderQuestion(){if(quiz.index>=quiz.queue.length)return quizDone();const q=current(),l=lessonFor(q.lesson);setPage(`<div class="eyebrow">TOPIC ${l.module} · ${esc(l.title)}</div>${bar(quiz.cleared.size,quiz.total,'This round: checks cleared')}<span class="c-tag">${q.retry?'Try it again':'Original practice'}</span><h1>${esc(q.prompt)}</h1><details><summary>Teach me first · the idea behind this question</summary>${l.teach.map(p=>`<p>${esc(p)}</p>`).join('')}<p><strong>Example:</strong> ${esc(l.example)}</p>${termDetails(l)}</details>${q.kind==='mc'?`<div class="c-options">${q.choices.map((s,i)=>`<button data-action="answer" data-value="${i}"><b>${String.fromCharCode(65+i)}</b><span>${esc(s)}</span></button>`).join('')}</div>`:`<p>${q.kind==='blank'?'Tap one word for each blank, in sentence order.':'Tap the pieces in order to build the answer.'} Tap a selected piece to put it back.</p><div id="career-picked" class="c-bank c-picked">${q.picked.length?q.picked.map((idx,i)=>btn('unpick',q.choices[idx],i)).join(''):'<span class="muted">Your answer goes here…</span>'}</div><div class="c-bank">${q.choices.map((s,i)=>q.picked.includes(i)?'':btn('pick',s,i)).join('')}</div><div class="c-actions"><button class="primary" data-action="check" ${q.picked.length!==q.answer.length?'disabled':''}>Check answer</button>${btn('clear','Start this answer over')}</div>`}<div id="career-feedback" role="status" aria-live="polite"></div><div class="c-actions">${btn('view','Leave round','learn')}</div>`)}
function grade(answer){if(!quiz||quiz.graded)return;const q=current(),ok=JSON.stringify(answer)===JSON.stringify(q.answer);quiz.graded=true;quiz.attempts++;if(!q.retry&&ok)quiz.first++;if(ok){quiz.cleared.add(q.id);saved.passed[q.id]=true;delete saved.review[q.id]}else{saved.review[q.id]=true;delete saved.passed[q.id];const again=prepare({...q,retry:true});quiz.queue.splice(Math.min(quiz.index+3,quiz.queue.length),0,again)}persist();document.querySelectorAll('[data-action="answer"],[data-action="pick"],[data-action="unpick"],[data-action="check"],[data-action="clear"]').forEach(b=>b.disabled=true);$('#career-feedback').innerHTML=`<div class="c-feedback ${ok?'':'wrong'}"><h2>${ok?'Correct — here’s why':'Not yet — let’s make it clear'}</h2><div class="eyebrow">CORRECT ANSWER</div><p class="c-answer">${esc(Array.isArray(q.answer)?q.answer.join(q.kind==='blank'?' · ':' → '):q.answer)}</p><p>${esc(q.why)}</p>${!ok?'<p><strong>You will try this again later in this round.</strong> When it is the last remaining check, it comes next.</p>':''}${btn('next-question','Continue','','primary')}</div>`;$('#career-feedback').scrollIntoView({behavior:'smooth',block:'nearest'})}
function quizDone(){if(quiz.lesson){saved.read[quiz.lesson]=true;persist()}setPage(`<div class="c-hero"><div class="eyebrow">ROUND COMPLETE</div><h1>Every check cleared ✓</h1><p>You answered all ${quiz.total} checks correctly, including any retries.</p></div>${bar(quiz.cleared.size,quiz.total,'Complete')}<p>${quiz.first} correct on the first attempt · ${quiz.attempts} total attempts. Come back later to strengthen recall.</p><div class="c-actions">${quiz.lesson?btn('continue','Next lesson',quiz.lesson,'primary'):btn('practice','Another mixed round','mixed','primary')}${btn('view','Try explaining it aloud','interview')}${btn('view','Back to learning','learn')}</div>`);focusPage()}
function interviews(){const ids=new Set(lessons().map(l=>l.id));return C.interviews.filter(i=>ids.has(i.lesson))}
function interviewHome(){const pool=interviews();setPage(`<div class="eyebrow">SAY IT OUT LOUD · NO TYPING</div><h1>Practice the conversation.</h1><p>These are original, representative questions based on the researched skills. They are not a leaked question bank or a promise of what a company will ask.</p><div class="c-note"><p>Answer aloud for about 1–2 minutes. Then reveal the outline and check what you covered. Nothing is recorded and your speaking is not automatically graded.</p></div><div class="c-actions">${btn('mock','Start a 5-question mock','mixed','primary')}${btn('mock','Revisit answers needing work','review')}</div><h2>Choose a topic</h2><div class="c-list">${pool.map(i=>`<button data-action="single-interview" data-value="${esc(i.id)}"><span>${esc(i.prompt)}<small>${esc(lessonFor(i.lesson).title)} · ${saved.spoken[i.id]?esc(saved.spoken[i.id]):'Not self-reviewed yet'}</small></span><span>→</span></button>`).join('')}</div>`)}
function startMock(pool){if(!pool.length){setPage(`<h1>No answers marked “needs work.”</h1><p>Start a mock, then self-review each answer to build your review list.</p>${btn('mock','Start a mock','mixed','primary')}`);return}mock={items:pool,index:0,revealed:false,ratings:[]};renderMock();focusPage()}
function renderMock(){if(mock.index>=mock.items.length){setPage(`<h1>Mock complete ✓</h1><p>You self-reviewed ${mock.items.length} answers. ${mock.ratings.filter(x=>x==='needs work').length} marked for more practice.</p><div class="c-note"><p>This is your self-assessment, not an external evaluation. Rehearse with a person for feedback on clarity, correctness and follow-up questions.</p></div>${btn('mock','New mock','mixed','primary')} ${btn('view','Back to interview room','interview')}`);return}const i=mock.items[mock.index],l=lessonFor(i.lesson);setPage(`<div class="eyebrow">INTERVIEW ${mock.index+1} / ${mock.items.length} · ${esc(l.title)}</div><h1>${esc(i.prompt)}</h1><span class="c-tag">Original practice prompt</span><p>Take a breath. Answer aloud before revealing the outline. If it asks for experience, use a real event from class, work or a project.</p>${!mock.revealed?btn('reveal-mock','I’ve answered — show the self-check','','primary'):`<div class="c-card"><h2>A strong answer should cover…</h2><p>These are guideposts, not a script you must memorize.</p><div class="c-rubric">${i.outline.map((s,n)=>`<label><input type="checkbox" data-rubric="${n}">${esc(s)}</label>`).join('')}</div><h3>Try a follow-up</h3><p>${esc(i.followup)}</p><div class="c-actions">${btn('rate-mock','Needs work','needs work')}${btn('rate-mock','I explained the main points','practiced')}</div><small>Your rating is a self-assessment. Checkboxes help you review; they do not automatically score your speech.</small></div>${btn('lesson','Read the related lesson',l.id)}`}`)}
function terms(){const all=lessons().flatMap(l=>l.terms.map(t=>({...t,lesson:l.id})));setPage(`<div class="eyebrow">WORDS WITH A REAL JOB TO DO</div><h1>Flashcards & terms</h1><p>Flip a card to see the plain-language meaning. Definitions also appear inside the relevant lessons.</p>${btn('flash','Start flashcards','','primary')}<label for="term-search"><p>Find a term or abbreviation</p></label><input class="c-search" id="term-search" type="search" placeholder="Try API, authorization or stakeholder"><div id="term-results">${termList(all)}</div>`)}
function termList(list){return list.map(t=>`<details><summary>${esc(t.term)}</summary><p>${esc(t.definition)}</p>${btn('lesson','See it in context',t.lesson)}</details>`).join('')||'<p>No matching terms on this path.</p>'}
function startFlash(){flash={cards:shuffle(lessons().flatMap(l=>l.terms.map(t=>({...t,lesson:l.id})))),index:0,back:false};renderFlash()}
function renderFlash(){if(flash.index>=flash.cards.length){setPage(`<h1>Flashcard round complete ✓</h1><p>You reviewed every card in this round, including cards you asked to see again.</p>${btn('flash','Shuffle another round','','primary')} ${btn('view','Back to terms','terms')}`);return}const t=flash.cards[flash.index];setPage(`<div class="eyebrow">${esc(lessonFor(t.lesson).title)}</div><h1>Recall it before you flip.</h1><p>Card ${flash.index+1} of ${flash.cards.length}</p><button class="c-flash" data-action="flip"><small>${flash.back?'MEANING':'TERM'}</small><span>${esc(flash.back?t.definition:t.term)}</span><small>Tap to ${flash.back?'see the term':'reveal the meaning'}</small></button>${flash.back?`<div class="c-actions">${btn('flash-next','Show me again later','again')}${btn('flash-next','Got it','got','primary')}</div>`:''}`)}
const CASES=[
{id:'outage',module:2,title:'The checkout outage',lesson:'triage',intro:'You are an entry-level IT analyst. A store manager says “the internet is broken.” You can ask for evidence and choose the next safe step.',steps:[
{prompt:'What do you ask first?',options:['Which checkout action fails, who is affected, and what error appears?','Can I restart every network device immediately?','Can we replace all cashier passwords first?'],answer:0,why:'The complaint is broad. Scope and exact symptoms help distinguish payment, application and network problems.'},
{prompt:'All three registers can open other websites. Card payment returns “payment service unavailable.” What does that suggest?',options:['Investigate the payment service and its dependencies; do not conclude the whole internet is down.','The building has no network connection of any kind.','A working website proves every application is healthy.'],answer:0,why:'Working sites are evidence of some connectivity. The payment error narrows the investigation but does not yet establish a root cause.'},
{prompt:'A recent payment-service release matches the start time. What next?',options:['Escalate with impact, times and errors; ask the service owner to evaluate an approved recovery action.','Declare the release guilty and erase its logs.','Make an unapproved rollback without checking data impact.'],answer:0,why:'Timing is a lead. The responsible team can inspect evidence and choose a safe response while preserving information.'},
{prompt:'The service owner applies a fix. What closes the loop?',options:['Test actual payment with an authorized procedure, confirm with users and document the result.','Close the ticket because the change command completed.','Assume silence from the manager proves every payment succeeded.'],answer:0,why:'A completed change is not the same as restored business work. Verify the original task and communicate the outcome.'}]},
{id:'requirements-case',module:5,title:'“Make order search faster”',lesson:'requirements',intro:'A business team asks for a faster order tool. Work from an unclear request to an agreed test.',steps:[
{prompt:'Which opening question is most useful?',options:['Show me how you find an order now and where you lose time.','Which database brand should replace the current one?','Should every field be removed from the search screen?'],answer:0,why:'Observation can reveal whether waiting, repeated entry or missing information causes the delay.'},
{prompt:'Users spend most time copying order IDs between screens. What should you do?',options:['Validate that cause and consider connecting the workflow before buying faster servers.','Ignore the observation because speed always means processor speed.','Set a two-second server target without discussing the copying step.'],answer:0,why:'The measured problem is a handoff in the workflow. Infrastructure performance alone may not address it.'},
{prompt:'Which acceptance criterion checks the proposed improvement?',options:['From an open ticket, an authorized user can open its matching order without retyping the order ID.','The tool should feel very futuristic.','Every user must like all colors on the screen.'],answer:0,why:'This describes an observable action tied to the reported delay. Add error, permission and performance cases as relevant.'}]},
{id:'audit-case',module:7,title:'A departed employee still has access',lesson:'accessaudit',intro:'You are assisting an IT audit. A policy requires accounts disabled within 24 hours of departure. Your sample includes one account disabled after 72 hours.',steps:[
{prompt:'What can you conclude from this evidence?',options:['The sampled account missed the policy timing; investigate the cause and scope.','Every employee account has been compromised.','The control worked perfectly because access was eventually removed.'],answer:0,why:'72 hours exceeds 24. That supports an exception for this item, not a claim about every account or proven misuse.'},
{prompt:'What additional evidence helps?',options:['Departure and disable timestamps, account identity, policy and any approved exception records.','Only a verbal promise that the account was harmless.','The color of the employee’s laptop.'],answer:0,why:'Linking records to the same person and policy makes the comparison reliable. Exceptions need evidence and evaluation.'},
{prompt:'How do you present the issue?',options:['State the criterion, observed gap, potential impact and corrective owner/action without claiming unproven theft.','State that data theft definitely occurred because a control failed.','Remove the item because one exception cannot matter.'],answer:0,why:'A control failure can create exposure without proving harm occurred. A clear finding distinguishes those claims.'}]},
{id:'rollout-case',module:6,title:'A CRM rollout decision',lesson:'implementation',intro:'CRM means Customer Relationship Management. A company is moving customer records into a new sales application.',steps:[
{prompt:'The source has 1,000 records and the rehearsal loads 1,000. Is validation complete?',options:['No; inspect identifiers, field mappings, duplicates, values and realistic workflows.','Yes; equal counts prove every value and permission is right.','Yes; training is unnecessary if record counts match.'],answer:0,why:'You could load the correct number of rows into the wrong fields. Quantity alone does not establish accuracy.'},
{prompt:'Users cannot perform a common sales task in the rehearsal. What is the next step?',options:['Investigate whether the cause is requirements, configuration or training and retest before cutover.','Ignore it because the migration ran without a technical error.','Require users to accept the tool without understanding their task.'],answer:0,why:'Implementation succeeds when real work can be done. The cause might be a settings problem or unclear training, so inspect it.'},
{prompt:'How should the go-live plan address uncertainty?',options:['Define owners, acceptance checks, user support and an approved recovery plan.','Promise no defects will occur after launch.','Stop monitoring as soon as users receive login links.'],answer:0,why:'A planned transition includes how to detect and handle problems, not only the date the system becomes available.'}]}
];
function labsHome(){setPage(`<div class="eyebrow">APPLY IT · ORIGINAL SIMULATED CASES</div><h1>Think through the actual work.</h1><p>Choose the next action, learn why it fits, and see what happens next. These cases do not connect to real workplace systems.</p><div class="c-grid">${CASES.filter(c=>track().modules.includes(c.module)).map(c=>`<section class="c-card"><span class="c-tag">Topic ${c.module}</span><h2>${esc(c.title)}</h2><p>${esc(c.intro)}</p>${btn('case','Start case',c.id,'primary')}</section>`).join('')}${track().modules.includes(4)?`<section class="c-card"><span class="c-tag">DATA & SQL</span><h2>See a join happen</h2><p>Switch between two join types and watch which customer and order rows appear.</p>${btn('sql-lab','Open table explorer','','primary')}</section>`:''}</div>`)}
function startCase(id){lab={c:CASES.find(c=>c.id===id),index:0,right:0,attempted:false,cleared:false,choices:null};renderCase()}
function renderCase(){const c=lab.c;if(lab.index>=c.steps.length){saved.milestones['case-'+c.id]=true;persist();setPage(`<h1>Case complete ✓</h1><p>${lab.right} of ${c.steps.length} decisions correct on the first attempt. You worked through every step.</p><div class="c-note"><h2>Now explain your reasoning</h2><p>Summarize the problem, evidence, decision and verification aloud. What additional facts could change your recommendation?</p></div>${btn('lesson','Revisit the related lesson',c.lesson)} ${btn('view','Another case','labs','primary')}`);return}const s=c.steps[lab.index];if(!lab.choices)lab.choices=shuffle(s.options.map((text,i)=>({text,i})));setPage(`<div class="eyebrow">${esc(c.title)} · STEP ${lab.index+1}/${c.steps.length}</div><p>${esc(c.intro)}</p><h1>${esc(s.prompt)}</h1><div class="c-options">${lab.choices.map((o,n)=>`<button data-action="case-answer" data-value="${o.i}"><b>${String.fromCharCode(65+n)}</b><span>${esc(o.text)}</span></button>`).join('')}</div><div id="case-feedback" role="status"></div>`)}
function caseAnswer(n){if(lab.cleared)return;const s=lab.c.steps[lab.index],ok=n===s.answer;if(ok&&!lab.attempted)lab.right++;lab.attempted=true;lab.cleared=ok;$('#case-feedback').innerHTML=`<div class="c-feedback ${ok?'':'wrong'}"><h2>${ok?'That fits the evidence.':'Reconsider this step.'}</h2><p>${esc(s.why)}</p>${ok?btn('case-next','Continue','','primary'):'<p>Choose again using that explanation.</p>'}</div>`}
function sqlLab(type='left'){const left=type==='left';setPage(`<div class="eyebrow">TOPIC 4 · A VISUAL SQL EXAMPLE</div><h1>Match customers to their orders.</h1><p>Ana has two orders. Bo has none. Watch what happens to Bo when the join changes.</p><div class="c-grid"><div class="c-card"><h2>Customers</h2><table><tr><th>customer_id</th><th>name</th></tr><tr><td>1</td><td>Ana</td></tr><tr><td>2</td><td>Bo</td></tr></table></div><div class="c-card"><h2>Orders</h2><table><tr><th>order_id</th><th>customer_id</th></tr><tr><td>101</td><td>1</td></tr><tr><td>102</td><td>1</td></tr></table></div></div><div class="c-row"><button data-action="sql-lab" data-value="left" aria-pressed="${left}">LEFT JOIN</button><button data-action="sql-lab" data-value="inner" aria-pressed="${!left}">INNER JOIN</button></div><pre>SELECT c.name, o.order_id
FROM customers AS c
${left?'LEFT':'INNER'} JOIN orders AS o
  ON c.customer_id = o.customer_id;</pre><div class="c-card" aria-live="polite"><h2>Result: ${left?3:2} rows</h2><table><tr><th>name</th><th>order_id</th></tr><tr><td>Ana</td><td>101</td></tr><tr><td>Ana</td><td>102</td></tr>${left?'<tr><td>Bo</td><td>NULL — no matching order</td></tr>':''}</table><p>${left?'LEFT JOIN keeps Bo because he is a customer on the left, even though there is no matching order.':'INNER JOIN excludes Bo because there is no matching order.'} Ana appears twice because two orders match her identifier.</p></div><p class="c-callout">This is a fixed teaching example, not a live SQL execution environment.</p>${btn('lesson-practice','Try the join questions','join','primary')} ${btn('lesson','Read the join lesson','join')}`)}
function research(){setPage(`<div class="eyebrow">RESEARCHED 28 SEPTEMBER 2026 · U.S. ENTRY LEVEL</div><h1>Different titles. Different interviews.</h1><p>Start with the shared foundation, then use the actual job description to choose depth. “Entry level” does not mean every employer expects the same tools or uses the same assessment.</p><div class="c-note"><h2>What is verified, and what is practice?</h2><p>Employer pages below describe formats or responsibilities. The lessons, questions, cases and suggested preparation plan are our original synthesis. No public source can guarantee the exact questions in your future interview.</p></div><h2>Your target roles</h2><div class="c-grid">${C.tracks.filter(t=>t.id!=='all').map(t=>`<section class="c-card"><h3>${esc(t.title)}</h3><ul>${t.roles.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><p>${esc(t.about)}</p>${btn('choose-track','Use this path',t.id,'primary')}</section>`).join('')}</div><h2>What the evidence suggests preparing</h2><div class="c-table"><table><thead><tr><th>Area</th><th>What to be able to demonstrate</th><th>Evidence & limits</th></tr></thead><tbody><tr><td>IT & systems</td><td>Diagnose a problem, explain a system and communicate with users.</td><td>O*NET and Epic describe relevant work; this does not establish a universal interview script.</td></tr><tr><td>Business analysis</td><td>Clarify needs, map a process, define acceptance criteria and reason about data.</td><td>IIBA defines analysis concepts; SQL depth depends on the posting.</td></tr><tr><td>Consulting</td><td>Structure an ambiguous case, state assumptions and recommend next steps.</td><td>Deloitte publishes case guidance. Confirm whether your vacancy uses a case.</td></tr><tr><td>Solutions / implementation</td><td>Discover needs, demonstrate a relevant workflow, test a rollout and support adoption.</td><td>Presales and post-sale implementation are different jobs; inspect responsibilities.</td></tr><tr><td>Risk & audit</td><td>Link a risk to controls, evidence, exceptions and a justified conclusion.</td><td>ISACA provides a curriculum, not a guarantee of interview content or a required credential.</td></tr><tr><td>Technology programs</td><td>Behavioral and role-specific preparation; coding for software tracks.</td><td>Capital One documents program-dependent formats and a software-engineering TDP.</td></tr></tbody></table></div><h2>Build one small, honest work sample</h2><p>Choose a sample for your path. These are suggested projects, not required credentials.</p><div class="c-grid"><div class="c-card"><h3>IT / systems</h3><p>Document a safe lab problem: expected behavior, symptoms, tests, fix and verification. Explain what you learned and what you could not conclude.</p></div><div class="c-card"><h3>Business analysis / data</h3><p>Map a small process, write three requirements and acceptance tests, then analyze a tiny public or invented dataset. Explain your SQL joins or spreadsheet formulas.</p></div><div class="c-card"><h3>Consulting / implementation</h3><p>Compare two ways to improve a workflow. Present assumptions, costs, risks, a short demo and a rollout/testing plan.</p></div><div class="c-card"><h3>Risk / audit</h3><p>Use a fictional access list and policy. Describe the risk, control, test evidence and one finding with a limited, defensible conclusion.</p></div></div><h2>Ask the recruiter</h2><ul><li>Is this role eligible for a May 2027 graduate, and what is the expected start date?</li><li>Which interviews or assessments are used for this specific opening?</li><li>Will I write code or SQL, discuss a case, give a demo, or complete a take-home exercise?</li><li>Which skills must I bring on day one, and which are taught?</li><li>What would successful performance look like in the first 90 days?</li></ul><h2>Read the original sources</h2><p>Listings and interview processes change. A source describes the scope shown below; it is not an endorsement or a promise of an open job.</p>${C.sources.map(s=>`<section class="c-card" style="margin:14px 0"><span class="c-tag">${esc(s.kind)}</span><h3><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a></h3><p>${esc(s.note)}</p></section>`).join('')}`)}
function chooseTrack(id){saved.track=C.tracks.some(t=>t.id===id)?id:'all';$('#career-track').value=saved.track;persist();navigate('home')}
function act(action,value){switch(action){case 'view':navigate(value);break;case 'choose-track':chooseTrack(value);break;case 'lesson':openLesson(value);break;case 'continue':continueLesson(value);break;case 'lesson-practice':startQuiz(C.questions.filter(q=>q.lesson===value),value);break;case 'module-practice':startQuiz(questions().filter(q=>lessonFor(q.lesson).module===Number(value)));break;case 'practice':startQuiz(shuffle(questions()).slice(0,10));break;case 'review':startQuiz(questions().filter(q=>saved.review[q.id]));break;case 'answer':grade(current().choices[Number(value)]);break;case 'pick':if(!quiz.graded&&!current().picked.includes(Number(value))&&current().picked.length<current().answer.length){current().picked.push(Number(value));renderQuestion()}break;case 'unpick':if(!quiz.graded){current().picked.splice(Number(value),1);renderQuestion()}break;case 'clear':if(!quiz.graded){current().picked=[];renderQuestion()}break;case 'check':if(current().picked.length===current().answer.length)grade(current().picked.map(i=>current().choices[i]));break;case 'next-question':if(quiz.graded){quiz.index++;quiz.graded=false;renderQuestion();focusPage()}break;case 'mock':{let pool=interviews();if(value==='review')pool=pool.filter(i=>saved.spoken[i.id]==='needs work');else {const intro=pool.find(i=>i.lesson==='intro'),behavior=pool.find(i=>i.lesson==='star');pool=[intro,behavior,...shuffle(pool.filter(i=>![intro,behavior].includes(i))).slice(0,3)].filter(Boolean)}startMock(pool);break}case 'single-interview':startMock([C.interviews.find(i=>i.id===value)]);break;case 'reveal-mock':mock.revealed=true;renderMock();break;case 'rate-mock':saved.spoken[mock.items[mock.index].id]=value;mock.ratings.push(value);persist();mock.index++;mock.revealed=false;renderMock();focusPage();break;case 'flash':startFlash();break;case 'flip':flash.back=!flash.back;renderFlash();break;case 'flash-next':if(value==='again')flash.cards.splice(Math.min(flash.index+4,flash.cards.length),0,flash.cards[flash.index]);flash.index++;flash.back=false;renderFlash();break;case 'case':startCase(value);break;case 'case-answer':caseAnswer(Number(value));break;case 'case-next':if(lab.cleared){lab.index++;lab.attempted=false;lab.cleared=false;lab.choices=null;renderCase();focusPage()}break;case 'sql-lab':sqlLab(value||'left');break}}
async function init(){try{const r=await fetch('career-content.json');if(!r.ok)throw new Error('Content unavailable');C=await r.json();restore();$('#career-track').innerHTML=C.tracks.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('');$('#career-track').value=saved.track;nav();home()}catch(e){setPage('<h1>Career could not load.</h1><p>Please reload the page. If you opened this as a file, use the app’s local server or deployed website.</p>')}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)act(b.dataset.action,b.dataset.value)});
document.addEventListener('change',e=>{if(e.target.id==='career-track')chooseTrack(e.target.value);if(e.target.dataset.milestone!==undefined){saved.milestones[e.target.dataset.milestone]=e.target.checked;persist()}});
document.addEventListener('input',e=>{if(e.target.id==='term-search'){const search=e.target.value.toLowerCase();$('#term-results').innerHTML=termList(lessons().flatMap(l=>l.terms.map(t=>({...t,lesson:l.id}))).filter(t=>(t.term+' '+t.definition).toLowerCase().includes(search)))}});
init();
